def flood_fill(i, j, inp, color):
    """Do BFS to find connected region of same color. Returns set of (i,j)"""
    if visited[i][j]:
        return set()
    region = set()
    stack = [(i,j)]
    while stack:
        cur_i, cur_j = stack.pop()
        if visited[cur_i][cur_j]:
            continue
        visited[cur_i][cur_j] = True
        if inp[cur_i][cur_j] == color:
            region.add((cur_i, cur_j))
            for di, dj in [(-1,0), (1,0), (0,-1), (0,1)]:
                ni, nj = cur_i+di, cur_j+dj
                if 0 <= ni < r and 0 <= nj < c and not visited[ni][nj]:
                    stack.append((ni, nj))
    return region

