from collections import deque

def flood_from_boundary_with_exclusions(grid):
    """
    Flood fill from all boundary cells with values NOT excluded.
    Returns set of cells reachable from boundary.
    Excluded values (can't pass through) are 3 and 5.
    """
    r,c = len(grid), len(grid[0])
    q = deque()
    visited = set()

    # Add all boundary cells not equal to 3 or 5
    for i in [0, r-1]:
        for j in range(c):
            if grid[i][j] not in [3, 5]:
                q.append((i,j))
                visited.add((i,j))
    for j in [0, c-1]:
        for i in range(1, r-1):
            if grid[i][j] not in [3, 5]:
                if (i,j) not in visited:
                    q.append((i,j))
                    visited.add((i,j))

    while q:
        ci, cj = q.popleft()
        for di, dj in [(-1,0), (1,0), (0,-1), (0,1)]:
            ni, nj = ci+di, cj+dj
            if 0 <= ni < r and 0 <= nj < c:
                if (ni,nj) not in visited and grid[ni][nj] not in [3, 5]:
                    visited.add((ni,nj))
                    q.append((ni,nj))

    return visited

